import {getWord} from '../content.js';
import {header,go,section,icon,escape} from '../ui.js';
export function render(state) {
 const active=state.reviews.filter(r=>r.status!=='done');const done=state.reviews.filter(r=>r.status==='done');
 return `${header('让记忆再见一次','复习点 · 有依据，有下一步')}<div class="review-summary"><strong>${active.filter(r=>!r.paused).length}<span>待练习</span></strong><p>把薄弱处留给下一次。<br>完成练习后，再更新它的证据。</p></div>${section('我的复习点',go('加入一个词 ↗','coach','text-button'))}${active.length?active.map(r=>`<article class="review-item"><div class="review-item-title"><div><h2>${getWord(r.wordId).word}</h2><span class="muted">${getWord(r.wordId).ipa}</span></div><span class="skill-tag">${escape(r.skill)}</span></div><p class="review-source">${escape(r.source)}</p><div class="review-schedule"><span class="dot ${r.paused?'gray':''}"></span>${r.paused?'已暂停':r.status==='pending'?'演示已加入 · 等待安排':escape(r.when)}</div>${r.skill==='发音'?'<p class="small-note left">跟读与自听练习 · 未自动评测</p>':''}<div class="review-item-actions">${r.status==='pending'?go('安排到计划','plan','primary compact'):go('开始练习','','primary compact',`data-action="review-start" data-id="${escape(r.id)}" ${r.paused?'disabled':''}`)}<button class="text-button" data-action="review-pause" data-id="${escape(r.id)}">${r.paused?'恢复复习':'暂停'}</button></div></article>`).join(''):'<div class="empty-state">今天的复习点已练完。<p>可以去学新词，或和教练加入下一次练习。</p></div>'}${done.length?`<details class="completed-list"><summary>已完成练习 · ${done.length} 项</summary>${done.map(r=>`<p>${getWord(r.wordId).word} · ${escape(r.skill)} · 演示自练完成</p>`).join('')}</details>`:''}<p class="small-note">收录与安排是两件事；不会把加入复习当作已经练过。</p>`;
}
